// Course data, generated by scripts/build-data.mjs from the book plan + your original curriculum.
import data from "./curriculum.json";

export const BOOK = data.book;
export const DAYS = data.days;
export const TOTAL_DAYS = DAYS.length;
export const TOTAL_WORDS = DAYS.reduce((n, d) => n + d.words.length, 0);

export const getDay = (n) => DAYS.find((d) => d.day === n);

